fn swap_values(a: &mut i32, b: &mut i32) {
    let pa = a as *mut i32;
    let pb = b as *mut i32;
    // SAFETY: two &mut are never the same place, and both are alive.
    unsafe {
        let saved = *pa;
        *pa = *pb;
        *pb = saved;
    }
}

fn main() {
    let (mut x, mut y) = (1, 2);
    swap_values(&mut x, &mut y);
    println!("{x} {y}");
}
